<template>
  <el-alert v-if="error" :title="error" type="error" :closable="false" class="pose-error"/>
  <div class="pose-stat-grid"><div class="pose-stat"><small>模型版本</small><strong>{{ models.length }}<em>个</em></strong></div><div class="pose-stat"><small>正在使用</small><strong class="pose-accent">{{ activeModel?'v'+activeModel.version_no:'未配置' }}</strong></div><div class="pose-stat"><small>增量更新</small><strong>{{ learning?.policy?.enabled?'已开启':'未开启' }}</strong></div><div class="pose-stat"><small>待更新实测点</small><strong>{{ learning?.state?.newSamples??0 }}<em>点</em></strong></div></div>
  <div class="pose-model-layout">
    <section class="pose-panel pose-model-list">
      <header class="pose-panel-header"><h3>模型版本仓库</h3><div class="pose-inline-actions"><el-button :loading="loading" @click="load">刷新</el-button><el-button type="primary" @click="openImport">导入已有模型</el-button></div></header>
      <div class="pose-table"><el-table :data="models" v-loading="loading" style="width:100%" @row-click="selected=$event">
        <el-table-column label="模型 / 版本" min-width="180"><template #default="{row}"><div class="pose-model-name"><b>{{ row.model_name }}</b><small>v{{ row.version_no }} · ID {{ row.model_version_id }}</small></div></template></el-table-column>
        <el-table-column label="来源" min-width="110"><template #default="{row}">{{ row.create_by==='incremental-learning'?'自动增量更新':'已登记模型' }}</template></el-table-column>
        <el-table-column label="大小" width="100"><template #default="{row}">{{ sizeLabel(row.file_size) }}</template></el-table-column>
        <el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="isActive(row)?'success':'info'">{{ isActive(row)?'正在使用':'可用' }}</el-tag></template></el-table-column>
        <el-table-column prop="create_time" label="登记时间" min-width="160"/>
        <el-table-column label="操作" min-width="180"><template #default="{row}"><el-button link type="primary" :disabled="isActive(row)||activating" @click.stop="activate(row)">启用</el-button><el-button link type="primary" @click.stop="download(row)">下载</el-button><el-button link type="danger" :disabled="isActive(row)" @click.stop="archive(row)">归档</el-button></template></el-table-column>
      </el-table></div>
      <div v-if="!models.length&&!loading" class="pose-empty"><b>先导入一个现有模型</b><span>系统在现有权重上持续更新。模型可为 ZIP、PyTorch 权重或 ONNX 包。</span><el-button type="primary" @click="openImport">导入已有模型</el-button></div>
      <div v-if="selected" class="pose-panel-body"><div class="pose-title-small">所选版本信息 · {{ selected.model_name }} v{{ selected.version_no }}</div><dl class="pose-facts"><div><dt>原始文件</dt><dd>{{ selected.original_name }}</dd></div><div><dt>SHA-256</dt><dd style="max-width:75%">{{ selected.sha256 }}</dd></div><div><dt>评估指标</dt><dd>{{ metricsLabel(selected.metrics_json) }}</dd></div></dl></div>
    </section>
    <aside class="pose-context">
      <section class="pose-panel"><header class="pose-panel-header"><h3>当前推理配置</h3></header><div class="pose-panel-body"><dl class="pose-facts"><div><dt>模型</dt><dd>{{ activeModel?.model_name||'—' }}</dd></div><div><dt>版本</dt><dd>{{ activeModel?'v'+activeModel.version_no:'—' }}</dd></div></dl><el-form label-position="top" style="margin-top:18px"><el-form-item label="推理适配器"><el-select v-model="inferenceScript" placeholder="选择模型对应的适配器"><el-option v-for="item in inferenceTemplates" :key="item.template_id" :label="item.template_name" :value="item.runtime_path"/></el-select></el-form-item></el-form><el-button type="primary" :loading="activating" :disabled="!activeModel||!inferenceScript" @click="activate(activeModel)">保存推理配置</el-button><el-button link type="primary" style="margin:12px 0 0" @click="adapterOpen=true">登记模型适配器</el-button></div></section>
      <section class="pose-panel"><header class="pose-panel-header"><h3>自动增量更新</h3><el-tag :type="learning?.policy?.enabled?'success':'info'">{{ learning?.policy?.enabled?'已开启':'未开启' }}</el-tag></header><div class="pose-panel-body"><dl class="pose-facts"><div><dt>运行状态</dt><dd>{{ learningStatus(learning?.state?.status) }}</dd></div><div><dt>新增样本</dt><dd>{{ learning?.state?.newSamples??0 }} / {{ learning?.policy?.minimumNewSamples??10 }}</dd></div><div><dt>学习率</dt><dd>{{ learning?.policy?.learningRate??0.0001 }}</dd></div><div><dt>更新轮数</dt><dd>{{ learning?.policy?.epochs??3 }}</dd></div><div><dt>数据进度</dt><dd>{{ formatNumber(learning?.state?.trainedThroughMd,1) }} m</dd></div></dl><p v-if="learning?.state?.error" class="pose-muted">{{ learning.state.error }}</p><el-button type="primary" style="width:100%;margin-top:18px" @click="policyOpen=true">设置增量更新参数</el-button><el-button style="width:100%;margin:10px 0 0" @click="historyOpen=true">查看自动更新记录</el-button></div></section>
    </aside>
  </div>
  <IncrementalLearningDialog v-model="policyOpen" :field-id="fieldId" :policy="learning?.policy" :wells="wells" :templates="incrementalTemplates" @saved="learning=$event"/>
  <ResizableDialog v-model="importOpen" title="导入已有模型" width="560px" class="pose-dialog" append-to-body>
    <el-form label-position="top"><el-form-item label="模型名称"><el-input v-model="importForm.name" placeholder="例如 井眼轨迹预测模型" maxlength="100"/></el-form-item><el-form-item label="权重 / 模型包"><input class="pose-select-file" type="file" accept=".zip,.pt,.pth,.onnx,.json" @change="importForm.file=$event.target.files?.[0]"/></el-form-item></el-form>
    <template #footer><el-button @click="importOpen=false">取消</el-button><el-button type="primary" :loading="uploading" @click="importModel">确 定</el-button></template>
  </ResizableDialog>
  <ResizableDialog v-model="adapterOpen" title="登记模型适配器" width="560px" class="pose-dialog" append-to-body>
    <el-form label-position="top"><el-form-item label="名称"><el-input v-model="adapter.name" placeholder="模型推理或增量更新适配器"/></el-form-item><el-form-item label="用途"><el-select v-model="adapter.role"><el-option label="模型推理" value="INFERENCE"/><el-option label="增量更新" value="INCREMENTAL"/></el-select></el-form-item><el-form-item label="Python 适配脚本"><input class="pose-select-file" type="file" accept=".py" @change="adapter.file=$event.target.files?.[0]"/></el-form-item></el-form>
    <template #footer><el-button @click="adapterOpen=false">取消</el-button><el-button type="primary" :loading="uploading" @click="registerAdapter">确 定</el-button></template>
  </ResizableDialog>
  <ResizableDialog v-model="historyOpen" title="自动增量更新记录" @opened="drawLoss" width="940px" class="pose-dialog" append-to-body>
    <el-table :data="learning?.history||[]" @row-click="inspectUpdate"><el-table-column prop="create_time" label="提交时间" min-width="160"/><el-table-column label="状态" min-width="140"><template #default="{row}">{{ learningStatus(row.status) }}</template></el-table-column><el-table-column label="实测范围（MD）" min-width="155"><template #default="{row}">{{ formatNumber(decode(row.hyperparams_json).from_md,1) }}–{{ formatNumber(decode(row.hyperparams_json).to_md,1) }}</template></el-table-column><el-table-column label="来源模型" width="100"><template #default="{row}">{{ decode(row.hyperparams_json).parent_model_version_id }}</template></el-table-column><el-table-column prop="model_version_id" label="生成版本" width="100"/><el-table-column label="操作" width="95"><template #default="{row}"><el-button link type="primary" @click.stop="inspectUpdate(row)">日志</el-button></template></el-table-column></el-table>
    <div v-if="updateDetail"><div class="pose-state-line"><span>{{ learningStatus(updateDetail.status) }}</span><el-button v-if="['QUEUED','RUNNING'].includes(updateDetail.status)" type="danger" link @click="stopUpdate">终止本次更新</el-button></div><p v-if="updateDetail.error" class="pose-muted">{{ updateDetail.error }}</p><div ref="lossEl" class="pose-metrics-chart"></div><pre class="pose-log">{{ (updateDetail.logs||[]).join('\n')||'暂无运行日志' }}</pre></div>
  </ResizableDialog>
</template>
<script setup>
import ResizableDialog from '@/components/ResizableDialog.vue'
import { computed, nextTick, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import * as echarts from '@/utils/drillingCharts'
import { downloadModel, getTrainingStatus, listModels, stopTraining } from '@/api/drilling'
import { createFieldConfig, createTrainingTemplate, listTrainingTemplates, uploadFieldFile } from '@/api/drillingField'
import { useDrillingContext } from '../../composables/useDrillingContext'
import IncrementalLearningDialog from './IncrementalLearningDialog.vue'
import { archivePredictionModel, decode, downloadBlob, formatNumber, getIncrementalLearning, learningStatus, registerPredictionModel } from './api'
const { fieldId,wells,configForm,loadFields,loadFieldContext }=useDrillingContext()
const models=ref([]),templates=ref([]),learning=ref(null),loading=ref(false),activating=ref(false),error=ref(''),selected=ref(null),inferenceScript=ref('')
const policyOpen=ref(false),historyOpen=ref(false),importOpen=ref(false),adapterOpen=ref(false),uploading=ref(false),updateDetail=ref(null),lossEl=ref(null)
const importForm=reactive({name:'',file:null}),adapter=reactive({name:'',file:null,role:'INFERENCE'})
let timer,chart,mounted=false,generation=0
const activeModel=computed(()=>models.value.find(row=>Number(row.model_version_id)===Number(configForm.algorithmDefaults.prediction.modelVersionId)))
const inferenceTemplates=computed(()=>templates.value.filter(row=>decode(row.hyperparam_schema_json).capability!=='INCREMENTAL'))
const incrementalTemplates=computed(()=>templates.value.filter(row=>decode(row.hyperparam_schema_json).capability!=='INFERENCE'))
const isActive=row=>Number(row.model_version_id)===Number(activeModel.value?.model_version_id)
const sizeLabel=value=>!Number.isFinite(Number(value))?'—':Number(value)>1024*1024?(Number(value)/1024/1024).toFixed(1)+' MB':(Number(value)/1024).toFixed(1)+' KB'
function metricsLabel(raw){const parsed=decode(raw);const last=Array.isArray(parsed)?parsed.at(-1):parsed;return last&&Object.keys(last).length?Object.entries(last).filter(([key])=>['loss','metric','mae','rmse','val_loss'].includes(key)).map(([key,value])=>key+' '+formatNumber(value,4)).join(' · ')||'暂无评估指标':'暂无评估指标'}
async function load(){if(!fieldId.value)return;const run=++generation;loading.value=true;error.value='';try{await loadFieldContext();const [modelData,templateData,learningData]=await Promise.all([listModels(fieldId.value),listTrainingTemplates(fieldId.value),getIncrementalLearning(fieldId.value)]);if(run!==generation)return;models.value=modelData.models||[];templates.value=templateData||[];learning.value=learningData;inferenceScript.value=configForm.algorithmDefaults.prediction.templateRuntimePath||'';if(selected.value)selected.value=models.value.find(row=>row.model_version_id===selected.value.model_version_id)||null}catch(e){error.value=e.message||'模型仓库加载失败'}finally{if(run===generation)loading.value=false}}
async function activate(row){if(!inferenceScript.value){ElMessage.warning('请先选择该模型对应的推理适配器');return}activating.value=true;try{await loadFieldContext();const snapshot=JSON.parse(JSON.stringify(configForm));snapshot.algorithmDefaults.prediction.modelVersionId=row.model_version_id;snapshot.algorithmDefaults.prediction.templateRuntimePath=inferenceScript.value;await createFieldConfig(fieldId.value,snapshot);await load();ElMessage.success('已启用模型版本及推理配置')}catch(e){ElMessage.error(e.message||'模型启用失败')}finally{activating.value=false}}
async function download(row){try{downloadBlob(await downloadModel(row.model_version_id,fieldId.value),row.original_name||'model.zip')}catch(e){ElMessage.error(e.message||'下载失败')}}
async function archive(row){try{await ElMessageBox.confirm(`归档 ${row.model_name} v${row.version_no}？历史预测记录会保留。`,'归档模型',{type:'warning'});await archivePredictionModel(fieldId.value,row.model_version_id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'归档失败')}}
function openImport(){importForm.name='';importForm.file=null;importOpen.value=true}
async function importModel(){if(!importForm.name.trim()||!importForm.file){ElMessage.warning('填写名称并选择已有模型文件');return}uploading.value=true;try{const data=new FormData();data.append('file',importForm.file);data.append('category','MODEL');const file=await uploadFieldFile(fieldId.value,data);await registerPredictionModel(fieldId.value,{fileId:file.file_id,modelName:importForm.name});importOpen.value=false;await load();ElMessage.success('模型已导入，可选择适配器后启用')}catch(e){ElMessage.error(e.message||'模型导入失败')}finally{uploading.value=false}}
async function registerAdapter(){if(!adapter.name.trim()||!adapter.file){ElMessage.warning('填写名称并选择适配脚本');return}uploading.value=true;try{const data=new FormData();data.append('file',adapter.file);data.append('category','TEMPLATE');data.append('template','true');const file=await uploadFieldFile(fieldId.value,data);await createTrainingTemplate(fieldId.value,{fileId:file.file_id,templateName:adapter.name,framework:'MODEL_ADAPTER',hyperparamSchema:{capability:adapter.role}});adapterOpen.value=false;await load();ElMessage.success('模型适配器已登记')}catch(e){ElMessage.error(e.message||'适配器登记失败')}finally{uploading.value=false}}
async function inspectUpdate(row){try{updateDetail.value=await getTrainingStatus(row.external_task_id||row.training_task_id);await drawLoss()}catch(e){ElMessage.error(e.message||'更新日志加载失败')}}
async function drawLoss(){await nextTick();if(!lossEl.value)return;chart?.dispose();chart=echarts.init(lossEl.value);const rows=updateDetail.value?.metrics||[],style=getComputedStyle(document.documentElement),text=style.getPropertyValue('--el-text-color-regular').trim()||'#606266',border=style.getPropertyValue('--el-border-color-light').trim()||'#dcdfe6';chart.setOption({animation:false,backgroundColor:'transparent',textStyle:{color:text},tooltip:{trigger:'axis'},grid:{top:25,left:55,bottom:30,right:20},xAxis:{type:'value',name:'Epoch',minInterval:1,axisLine:{lineStyle:{color:border}},splitLine:{lineStyle:{color:border}},axisLabel:{color:text}},yAxis:{type:'value',name:'Loss',axisLine:{lineStyle:{color:border}},splitLine:{lineStyle:{color:border}},axisLabel:{color:text}},series:[{type:'line',data:rows.filter(row=>row.loss!=null).map(row=>[row.epoch,row.loss]),lineStyle:{color:'#1479a8'},itemStyle:{color:'#1479a8'}}]})}
async function stopUpdate(){try{await stopTraining(updateDetail.value.task_id);await load();ElMessage.success('已请求终止本次更新')}catch(e){ElMessage.error(e.message||'终止失败')}}
watch(fieldId,()=>{if(mounted){models.value=[];selected.value=null;load()}})
onMounted(async()=>{if(!fieldId.value||!wells.value.length)await loadFields();mounted=true;await load();timer=window.setInterval(async()=>{if(!fieldId.value||policyOpen.value||uploading.value)return;try{learning.value=await getIncrementalLearning(fieldId.value);if(updateDetail.value&&historyOpen.value)await inspectUpdate({external_task_id:updateDetail.value.task_id});const live=configForm.algorithmDefaults.prediction.modelVersionId;if(learning.value.state?.latestModelVersionId&&Number(learning.value.state.latestModelVersionId)!==Number(live)&&learning.value.policy.autoActivate)await load()}catch(e){error.value=e.message||'增量状态刷新失败'}},10000)})
onBeforeUnmount(()=>{generation++;window.clearInterval(timer);chart?.dispose()})
</script>
